function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 30000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value is an integer between -10000 and 10000.';
  if (!Number.isInteger(k) || k < 2 || k > 10000) return 'k is an integer between 2 and 10000.';
  return null;
}

