function subarraysDivByK(nums, k) {
  const seen = new Array(k).fill(0);
  seen[0] = 1;
  let prefix = 0;
  let count = 0;

  for (const num of nums) {
    prefix = (((prefix + num) % k) + k) % k;
    count += seen[prefix];
    seen[prefix]++;
  }
  return count;
}

